const MODEL = $env.CLAUDE_MODEL || 'claude-opus-5-5';
const EFFORT = $env.CLAUDE_EFFORT || 'low';

function claudeRequest(system, userText, schema, maxTokens = 16000) {
  return {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    fallbacks: 'default',
    output_config: { effort: EFFORT, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: userText }],
  };
}

function parseClaude(resp) {
  if (!resp || resp.error) throw new Error('API error: ' + JSON.stringify(resp && resp.error).slice(0, 500));
  if (resp.stop_reason === 'refusal') throw new Error('refused: ' + JSON.stringify(resp.stop_details));
  if (resp.stop_reason === 'max_tokens') throw new Error('output truncated at max_tokens');
  const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  return JSON.parse(text);
}

const SYSTEM = "You write first-contact business emails for a demand-intelligence business based in Calgary, Canada.\nWe have validated consumer demand for a product and offer it to a manufacturer or merchant in\nexchange for a commission on resulting sales, tracked with a dedicated discount code or link.\n\nWrite in the language requested (English, or Simplified Chinese for Chinese factories).\nKeep it under 180 words. Structure: one line on who we are; the demand we found with one or two\nconcrete numbers from the brief; what we propose (they build or stock the product, we send buyers,\ncommission on tracked sales); one clear next step (a 15-minute call or a sample quote).\nDo not reveal the raw source links, exact search phrases, or customer quotes in full: those are what\nthe merchant pays for. Do not invent numbers, certifications, or past clients. No hype, no emojis.";
const SCHEMA = {"type": "object", "properties": {"subject": {"type": "string"}, "body": {"type": "string"}}, "required": ["subject", "body"], "additionalProperties": false};

return $input.all().map(i => i.json).filter(r => r.merchant_id).map(r => {
  const lang = r.language === 'zh' ? 'Simplified Chinese' : 'English';
  const user = `Language: ${lang}
Recipient: ${r.name} (${r.kind}; categories: ${(r.categories || []).join(', ')})
Opportunity: ${r.title}
Scores: ${JSON.stringify(r.scores)}
Brief:
${r.brief_md}`;
  return { json: { opportunity_id: r.opportunity_id, merchant_id: r.merchant_id,
                   language: r.language, request: claudeRequest(SYSTEM, user, SCHEMA, 4000) } };
});

